-- Classic 1.60: vanilla graveyard team restrictions. 2026_09_30_01 wrote them as (27, graveyard, zone), but the core reads
-- SourceGroup = zone and SourceEntry = graveyard (ObjectMgr::FindGraveyardData), so all 63 were rejected at load and those
-- graveyards served both factions; its DELETE matched SourceEntry = zone and left retail team rows on the replaced zones
-- (e.g. Kharanos 101, Bloodhoof 89 one-faction where vanilla has them neutral).
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 27 AND `SourceGroup` IN (1,3,4,8,10,11,12,14,15,16,17,25,28,33,36,38,40,41,44,45,47,51,85,130,139,141,148,209,215,267,331,357,361,400,405,406,440,490,491,493,618,717,718,719,721,722,796,1176,1337,1377,1417,1477,1497,1519,1537,1581,1583,1584,1637,1638,1657,1941,1977,2017,2057,2100,2159,2257,2437,2557,2597,2677,2717,2917,2918,3277,3358,3428,3429,3456,3478);
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 27 AND (`SourceGroup`, `SourceEntry`) IN ((34,215),(90,141),(90,1657),(93,141),(94,85),(97,130),(98,36),(98,267),(100,1),(105,12),(106,12),(106,717),(106,1519),(106,2257),(106,2918),(149,36),(149,130),(149,209),(149,267),(189,15),(189,2159),(289,85),(429,85),(429,1497),(489,11),(509,28),(509,2057),(569,28),(569,85),(569,2057),(610,2597),(611,2597),(631,15),(631,2159),(649,14),(709,14),(729,2597),(749,2597),(750,2597),(751,2597),(769,3277),(770,3277),(771,3277),(772,3277),(850,14),(850,1637),(850,2437),(850,2917),(851,215),(851,1638),(852,1),(852,1537),(853,85),(853,1497),(854,717),(854,1519),(854,2257),(889,3358),(890,3358),(893,3358),(895,3358),(898,3358),(899,3358));
